<?php
declare(strict_types=1);
namespace ReadyFinance;
final class ChartService {
 public function __construct(private Core $c){}
 public function ready():bool{return (bool)$this->c->query("SELECT COUNT(*) FROM schema_migrations WHERE version='005_chart'")->fetchColumn();}
 public function upgrade():array {$c=$this->c;if(!$c->query('SELECT GET_LOCK("rpf_chart_upgrade",10)')->fetchColumn())throw new Fault('Upgrade is busy.',409);try{$migration=require dirname(__DIR__,3).'/database/005_chart.php';$migration($c->db);return ['ok'=>true];}finally{$c->query('SELECT RELEASE_LOCK("rpf_chart_upgrade")');}}
 public function roots(int $h):array {
  $c=$this->c;$roots=[];foreach(['asset'=>'Assets','liability'=>'Liabilities','income'=>'Income','expense'=>'Expenses','equity'=>'Equity'] as $class=>$label){$r=$c->one('SELECT id FROM ledger_accounts WHERE household_id=? AND system_key=?',[$h,'chart_root_'.$class]);$roots[$class]=$r?(int)$r['id']:$c->insert('ledger_accounts',['uuid'=>Core::uuid(),'household_id'=>$h,'name'=>$label,'class'=>$class,'system_key'=>'chart_root_'.$class,'is_group'=>1,'account_kind'=>'group']);}
  foreach(['receivable'=>['asset','Receivables'],'payable'=>['liability','Payables']] as $kind=>[$class,$label]){$r=$c->one('SELECT id FROM ledger_accounts WHERE household_id=? AND system_key=?',[$h,'chart_group_'.$kind]);$roots[$kind]=$r?(int)$r['id']:$c->insert('ledger_accounts',['uuid'=>Core::uuid(),'household_id'=>$h,'name'=>$label,'class'=>$class,'system_key'=>'chart_group_'.$kind,'is_group'=>1,'account_kind'=>'group','parent_id'=>$roots[$class]]);}return $roots;
 }
 public function attach(int $h,int $ledger,string $parentUuid='',string $kind='general'):void {
  if(!$this->ready()){if($parentUuid!=='')throw new Fault('Enable the chart of accounts first.');return;}$c=$this->c;$leaf=$c->one('SELECT * FROM ledger_accounts WHERE household_id=? AND id=?',[$h,$ledger]);$roots=$this->roots($h);$parent=$parentUuid!==''?$c->scope('ledger_accounts',$parentUuid,$h):$c->one('SELECT * FROM ledger_accounts WHERE household_id=? AND id=?',[$h,$roots[in_array($kind,['receivable','payable'],true)?$kind:$leaf['class']]]);
  if(!(int)($parent['active']??1))throw new Fault('Restore the parent group first.');if(!$parent['is_group']||$parent['class']!==$leaf['class']||$parent['id']===$ledger)throw new Fault('Choose a parent group in the same account class.');
  $ancestor=$parent;$depth=0;while($ancestor){if(++$depth>20)throw new Fault('Use at most 20 levels of account groups.');$ancestor=$ancestor['parent_id']?$c->one('SELECT parent_id FROM ledger_accounts WHERE household_id=? AND id=?',[$h,$ancestor['parent_id']]):null;}
  $c->query('UPDATE ledger_accounts SET parent_id=?,account_kind=? WHERE household_id=? AND id=?',[$parent['id'],$kind,$h,$ledger]);
 }
 public function create(int $h,int $u,array $p,string $key):array {
  if(!$this->ready())throw new Fault('Enable the chart first.');if(!preg_match('/^[a-zA-Z0-9_.:-]{8,180}$/D',$key))throw new Fault('Command key required.');$c=$this->c;$hash=hash('sha256',json_encode($p,JSON_THROW_ON_ERROR));
  return $c->atomic(function()use($c,$h,$u,$p,$key,$hash){$c->one('SELECT id FROM households WHERE id=? FOR UPDATE',[$h]);$old=$c->one('SELECT * FROM command_receipts WHERE household_id=? AND command_key=?',[$h,'chart:'.$key]);if($old){if($old['payload_hash']!==$hash)throw new Fault('Command key conflict.',409);return json_decode($old['result_json'],true);}
   $kind=$p['kind']??'';$map=['asset'=>'asset','receivable'=>'asset','liability'=>'liability','payable'=>'liability','income'=>'income','expense'=>'expense','equity'=>'equity','group_asset'=>'asset','group_liability'=>'liability','group_income'=>'income','group_expense'=>'expense','group_equity'=>'equity'];if(!isset($map[$kind]))throw new Fault('Choose an account class.');$class=$map[$kind];$group=str_starts_with($kind,'group_');$uuid=Core::uuid();$lid=$c->insert('ledger_accounts',['uuid'=>$uuid,'household_id'=>$h,'name'=>Core::text($p['name']??''),'class'=>$class,'is_group'=>$group?1:0,'account_kind'=>$group?'group':$kind]);$this->attach($h,$lid,(string)($p['parent_uuid']??''),$group?'group':$kind);
   if(!$group&&in_array($class,['income','expense'],true))$c->insert('categories',['uuid'=>Core::uuid(),'household_id'=>$h,'ledger_id'=>$lid,'name'=>Core::text($p['name']),'type'=>$class]);
   $result=['uuid'=>$uuid];$c->insert('command_receipts',['household_id'=>$h,'command_key'=>'chart:'.$key,'payload_hash'=>$hash,'result_json'=>json_encode($result),'created_at'=>Core::now()]);$c->audit($h,$u,'chart.account_created',$uuid,['class'=>$class,'kind'=>$kind]);return $result;
  });
 }
 public function report(int $h,string $from,string $to):array {
  if(!$this->ready())return ['ready'=>false];$from=Core::date($from);$to=Core::date($to);if($from>$to)throw new Fault('Start date must be before end date.');$c=$this->c;
  $rows=$c->all('SELECT a.*,ca.uuid category_uuid,m.uuid money_uuid FROM ledger_accounts a LEFT JOIN categories ca ON ca.ledger_id=a.id AND ca.household_id=a.household_id LEFT JOIN accounts m ON m.ledger_id=a.id AND m.household_id=a.household_id WHERE a.household_id=? ORDER BY a.name',[$h]);
  $movements=$c->all('SELECT jl.ledger_id,SUM(IF(je.effective_date<?,jl.debit-jl.credit,0)) opening,SUM(IF(je.effective_date>=?,jl.debit,0)) debit,SUM(IF(je.effective_date>=?,jl.credit,0)) credit,SUM(jl.debit-jl.credit) closing FROM journal_lines jl JOIN journal_entries je ON je.id=jl.journal_id WHERE jl.household_id=? AND je.effective_date<=? GROUP BY jl.ledger_id',[$from,$from,$from,$h,$to]);$by=[];foreach($movements as $m)$by[$m['ledger_id']]=$m;
  $index=[];foreach($rows as &$r){$m=$by[$r['id']]??[];$r['opening']=$m['opening']??'0.000000';$r['debit']=$m['debit']??'0.000000';$r['credit']=$m['credit']??'0.000000';$r['closing']=$m['closing']??'0.000000';$index[$r['id']]=&$r;}unset($r);
  // Ancestor rollups include own activity once; leaf trial-balance totals never count groups twice.
  foreach($rows as $leaf){if($leaf['is_group'])continue;$parent=$leaf['parent_id'];$visited=[];while($parent){if(isset($visited[$parent])||!isset($index[$parent]))throw new Fault('Account hierarchy is invalid.',500);$visited[$parent]=true;foreach(['opening','debit','credit','closing'] as $field)$index[$parent][$field]=bcadd($index[$parent][$field],$leaf[$field],6);$parent=$index[$parent]['parent_id'];}}
  $totalDr='0';$totalCr='0';$closingDr='0';$closingCr='0';$classes=array_fill_keys(['asset','liability','income','expense','equity'],'0.000000');
  foreach($rows as &$r){$creditNormal=in_array($r['class'],['liability','equity','income'],true);$r['normal_balance']=$creditNormal?bcsub('0',$r['closing'],6):$r['closing'];$r['period_balance']=$creditNormal?bcsub($r['credit'],$r['debit'],6):bcsub($r['debit'],$r['credit'],6);
   if(!$r['is_group']){$totalDr=bcadd($totalDr,$r['debit'],6);$totalCr=bcadd($totalCr,$r['credit'],6);if(bccomp($r['closing'],'0',6)>=0)$closingDr=bcadd($closingDr,$r['closing'],6);else $closingCr=bcsub($closingCr,$r['closing'],6);$value=in_array($r['class'],['income','expense'],true)?$r['period_balance']:$r['normal_balance'];$classes[$r['class']]=bcadd($classes[$r['class']],$value,6);}
  }unset($r);$profit=bcsub($classes['income'],$classes['expense'],6);
  $lifetimeProfit=$c->query("SELECT COALESCE(SUM(IF(a.class IN ('income','expense'),jl.credit-jl.debit,0)),0) FROM journal_lines jl JOIN ledger_accounts a ON a.id=jl.ledger_id JOIN journal_entries je ON je.id=jl.journal_id WHERE jl.household_id=? AND je.effective_date<=?",[$h,$to])->fetchColumn();
  return ['ready'=>true,'from'=>$from,'to'=>$to,'accounts'=>$rows,'totals'=>['debit'=>$totalDr,'credit'=>$totalCr,'closing_debit'=>$closingDr,'closing_credit'=>$closingCr,'classes'=>$classes,'profit'=>$profit,'retained_result'=>$lifetimeProfit,'balance_sheet_difference'=>bcsub(bcsub($classes['asset'],$classes['liability'],6),bcadd($classes['equity'],$lifetimeProfit,6),6)]];
 }
 public function ledger(int $h,string $uuid,string $from,string $to):array {
  if(!$this->ready())throw new Fault('Enable the chart first.');$account=$this->c->scope('ledger_accounts',$uuid,$h);if($account['is_group'])throw new Fault('Choose a posting subaccount for its ledger.');$from=Core::date($from);$to=Core::date($to);if($from>$to)throw new Fault('Invalid date range.');
  return ['account'=>$account,'opening'=>$this->c->query('SELECT COALESCE(SUM(jl.debit-jl.credit),0) FROM journal_lines jl JOIN journal_entries je ON je.id=jl.journal_id WHERE jl.household_id=? AND jl.ledger_id=? AND je.effective_date<?',[$h,$account['id'],$from])->fetchColumn(),'rows'=>$this->c->all('SELECT t.uuid,t.type,t.description,t.status,je.effective_date,SUM(jl.debit) debit,SUM(jl.credit) credit FROM journal_lines jl JOIN journal_entries je ON je.id=jl.journal_id JOIN transactions t ON t.id=je.transaction_id WHERE jl.household_id=? AND jl.ledger_id=? AND je.effective_date>=? AND je.effective_date<=? GROUP BY t.id,je.id ORDER BY je.effective_date,je.id LIMIT 1000',[$h,$account['id'],$from,$to])];
 }
}
